#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

void print128(i128 value) {
    if (value == 0) {
        cout << 0;
        return;
    }
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string result;
    while (value > 0) {
        result.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, m;
    cin >> n >> m;

    unordered_map<ll, ll> frequency;
    ll limit = min(n, m);

    if (limit <= 10000000)
        frequency.reserve(static_cast<size_t>(limit * 1.3) + 1);

    for (ll i = 1; i <= limit; ++i) {
        ll occurrences = (n - i) / m + 1;
        ll residue = static_cast<ll>(
            static_cast<i128>(i % m) * (i % m) % m
        );
        frequency[residue] += occurrences;
    }

    i128 answer = 0;
    for (const auto& [residue, count] : frequency) {
        ll complement = (m - residue) % m;
        auto it = frequency.find(complement);
        if (it != frequency.end())
            answer += static_cast<i128>(count) * it->second;
    }

    print128(answer);
    return 0;
}

