#include <iostream>
#include <algorithm>
#include <cmath>
using namespace std;

using ll = long long;
using i128 = __int128_t;

ll nn, m;

ll floorSqrt(ll x) {
    if (x <= 0) return 0;
    ll r = static_cast<ll>(sqrtl(static_cast<long double>(x)));
    while (static_cast<i128>(r + 1) * (r + 1) <= x) ++r;
    while (static_cast<i128>(r) * r > x) --r;
    return r;
}

bool sumOfTwoSquares(ll target) {
    ll left = 1;
    ll right = min(nn, floorSqrt(target - 1));

    while (left <= right) {
        i128 current = static_cast<i128>(left) * left
                     + static_cast<i128>(right) * right;

        if (current == target) return true;
        if (current < target)
            ++left;
        else
            --right;
    }
    return false;
}

bool isPerfectSquare(ll x) {
    if (x < 0) return false;
    ll root = floorSqrt(x);
    return static_cast<i128>(root) * root == x;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> nn >> m;

    if (m == 1) {
        cout << static_cast<i128>(nn) * nn;
        return 0;
    }

    ll limit = static_cast<ll>(static_cast<i128>(2) * nn * nn);
    ll answer = 0;

    for (ll value = m; value <= limit;) {
        if (sumOfTwoSquares(value)) {
            if (isPerfectSquare(value / 2))
                ++answer;
            else
                answer += 2;
        }

        if (value > limit - m) break;
        value += m;
    }

    cout << answer;
    return 0;
}

#include <iostream>
#include <cmath>
using namespace std;

using ll = long long;

ll nn, m;

ll integerSqrt(ll x) {
    ll r = static_cast<ll>(sqrtl(static_cast<long double>(x)));
    while ((__int128)(r + 1) * (r + 1) <= x) ++r;
    while ((__int128)r * r > x) --r;
    return r;
}

bool isSquare(ll x) {
    if (x < 0) return false;
    ll r = integerSqrt(x);
    return (__int128)r * r == x;
}

bool sumOfTwoSquares(ll value) {
    ll limit = min(nn, integerSqrt(value));

    for (ll i = 1; i <= limit; ++i) {
        ll remaining = value - i * i;
        ll root = integerSqrt(remaining);

        if (root >= 1 && root <= i && root <= nn &&
            (__int128)root * root == remaining) {
            return true;
        }
    }

    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> nn >> m;

    if (m == 1) {
        cout << nn * nn;
        return 0;
    }

    ll limit = 2 * nn * nn;
    ll ans = 0;

    for (ll value = m; value <= limit;) {
        if (sumOfTwoSquares(value)) {
            if (isSquare(value / 2))
                ++ans;
            else
                ans += 2;
        }

        if (value > limit - m) break;
        value += m;
    }

    cout << ans;
    return 0;
}

#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

void printInt128(i128 value) {
    if (value == 0) {
        cout << 0;
        return;
    }
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string result;
    while (value > 0) {
        result.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, m;
    cin >> n >> m;

    if (m == 1) {
        printInt128((i128)n * n);
        return 0;
    }

    i128 answer = 0;

    if (m <= n) {
        vector<int64> count(static_cast<size_t>(m), 0);
        const int64 cycles = n / m;
        const int64 remainder = n % m;

        for (int64 r = 0; r < m; ++r) {
            const int64 frequency =
                cycles + (r >= 1 && r <= remainder ? 1 : 0);
            const int64 squareResidue =
                static_cast<int64>((i128)r * r % m);
            count[static_cast<size_t>(squareResidue)] += frequency;
        }

        for (int64 r = 0; r < m; ++r) {
            const int64 complement = (m - r) % m;
            answer += (i128)count[static_cast<size_t>(r)] *
                      count[static_cast<size_t>(complement)];
        }
    } else {
        vector<int64> residues;
        residues.reserve(static_cast<size_t>(n));

        for (int64 i = 1; i <= n; ++i)
            residues.push_back(static_cast<int64>((i128)i * i % m));

        sort(residues.begin(), residues.end());

        for (size_t i = 0; i < residues.size();) {
            size_t j = i + 1;
            while (j < residues.size() && residues[j] == residues[i])
                ++j;

            const int64 complement = (m - residues[i]) % m;
            const auto range =
                equal_range(residues.begin(), residues.end(), complement);

            answer += (i128)(j - i) * (range.second - range.first);
            i = j;
        }
    }

    printInt128(answer);
    return 0;
}

